class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.random.uniform(-1, 1, dim)
        self.pop_size = max(20, int(np.sqrt(self.dim * 12)))

    def _evaluate(self, x, func):
        if self.evals >= self.budget: 
            return float('inf')
        x_clean = np.clip(x, -1.0, 1.0)
        f = func(x_clean)
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = x_clean.copy()
        return f

    def __call__(self, func, grad_func=None):
        # 1. LHS Initialization over the full 24D normalized space
        pop = lhs(n_samples=self.pop_size, n_dim=self.dim)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)

        fitness = np.full(self.pop_size, float('inf'))
        for i in range(self.pop_size):
            fitness[i] = self._evaluate(pop[i], func)

        F = 0.8
        CR = 0.9
        epochs = max(1, self.budget // self.pop_size)

        for gen in range(epochs):
            for i in range(self.pop_size):
                idxs = [j for j in range(self.pop_size) if j != i]
                r1, r2, r3 = np.random.choice(idxs, 3, replace=False)

                # Gradient-Augmented Resonance Mutation
                mutant = pop[r1] + F * (pop[r2] - pop[r3])

                if grad_func is not None:
                    g = grad_func(pop[i])
                    if g.shape[0] == 18:
                        # Adaptive resonance: amplify search along negative gradient
                        # dampen near boundaries to avoid cliffs
                        safe_mask = np.abs(pop[i][:18]) < 0.85
                        resonance_vec = np.zeros(self.dim)
                        resonance_vec[:18] = np.where(safe_mask, g, 0.0)
                        mutant -= 0.25 * resonance_vec

                mutant = np.clip(mutant, -1.0, 1.0)

                # Categorical-Enhanced Crossover (no manual discretization)
                crossover_mask = np.random.rand(self.dim) < CR
                crossover_mask[18:] = np.random.rand(6) < 0.85
                trial = np.where(crossover_mask, mutant, pop[i])

                f_trial = self._evaluate(trial, func)
                # Strict selection: only accept if valid and better
                if f_trial < fitness[i]:
                    pop[i] = trial
                    fitness[i] = f_trial

            # Periodic Gradient Refinement on Best Candidate
            if grad_func is not None and gen % 5 == 0:
                fixed_cats = self.best_x[18:24].copy()

                def cost_wrap(x_cont):
                    full_x = np.concatenate([x_cont, fixed_cats])
                    return self._evaluate(full_x, func)

                def grad_wrap(x_cont):
                    full_x = np.concatenate([x_cont, fixed_cats])
                    return grad_func(full_x)

                x0 = self.best_x[:18].astype(np.float64)
                minimize(cost_wrap, x0, jac=grad_wrap, method='L-BFGS-B', bounds=[(-1.0, 1.0)] * 18)

        return self.best_f, self.best_x

