        self.CR = 0.9
        self.success_F = []
        self.success_CR = []
        self.ls_steps = 10
        self.top_k = 4
        self.stagnation_limit = 6

    def _levy(self, size):
        u = self.rng.normal(0, 1, size)
        v = self.rng.normal(0, 1, size)
        return u / (np.abs(v) ** (1/1.5))

    def _cauchy(self, size):
