            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]
            gen_sF, gen_sCR = [], []

            # Compute gradient bias ONCE per generation to drastically reduce expensive calls
            grad_bias = np.zeros(24)
            if grad_func:
                try:
                    g = grad_func(x_best)
                    if g is not None and len(g) == 18:
                        grad_bias[:18] = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                        norm_g = np.linalg.norm(grad_bias)
                        if norm_g > 1e-8:
                            grad_bias[:18] *= 0.04  # Conservative step to maintain exploration
