            f_valid = fitness[valid_mask]
            if len(f_valid) > 2:
                f_mean = np.mean(f_valid) + 1e-8
                f_std = np.std(f_valid)
                CR = np.clip(0.5 + 0.5 * (f_std / f_mean), 0.1, 0.95)
                F = np.clip(0.3 + 0.7 * (1.0 - (np.min(f_valid) / f_mean)), 0.1, 0.8)
            else:
                CR, F = 0.9, 0.8

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]

            g_bias = np.zeros(24)
            if grad_func:
                try:
                    g = grad_func(x_best)
                    if g is not None and len(g) == 18:
                        g_c = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                        norm_g = np.linalg.norm(g_c) + 1e-8
                        g_bias[:18] = (g_c / norm_g) * 0.07 * grad_w
                        # Gradient divergence informs categorical exploration breadth
                        cat_step = np.clip(0.08 + 0.18 * np.mean(np.abs(g_c)), 0.05, 0.35)
                        f_scale = np.clip(0.8 + 0.2 * (1.0 - np.mean(np.abs(g_c)) / (np.mean(np.abs(g_c)) + 1e-6)), 0.5, 1.2)
                except Exception: pass

            for i in range(n_pop):
                if self.evals >= self.budget: break

                idxs = self.rng.choice(n_pop, 3, replace=False)
                while np.any(idxs == i): idxs = self.rng.choice(n_pop, 3, replace=False)

                v = x_best + F * (pop[idxs[0]] - pop[idxs[1]]) + g_bias
                v[:18] += self.rng.standard_normal(18) * 0.02 * f_scale
                v[18:] += self.rng.standard_normal(6) * cat_step
                v = np.clip(v, -1.0, 1.0)

                cr_mask = self.rng.random(24) < CR
                trial = np.where(cr_mask, v, pop[i])
                f_trial = self._evaluate(trial, func)

                # Gradient-guided adaptive cliff recovery
                if np.isinf(f_trial) and self.evals < self.budget:
                    if grad_func:
                        try:
                            g = grad_func(trial)
                            if g is not None:
                                # Step opposite to gradient to exit invalid region
                                jump = -np.concatenate([g, np.zeros(6)])
                                jump = np.clip(jump, -0.15, 0.15)
                                trial_j = np.clip(trial + jump, -1.0, 1.0)
                                f_trial = self._evaluate(trial_j, func)
                        except Exception: pass
                    if np.isinf(f_trial):
                        trial_j = np.clip(self.rng.uniform(-1.0, 1.0, 24), -1.0, 1.0)
                        f_trial = self._evaluate(trial_j, func)

                if f_trial < fitness[i]:
                    pop[i] = trial
                    fitness[i] = f_trial
                    if np.isfinite(f_trial):
                        self.cat_archive.append(trial[18:].copy())
                        if len(self.cat_archive) > 25: self.cat_archive.pop(0)
                else:
                    self.stag += 1

            if self.stag > 12:
                self.stag = 0
                # Force categorical diversity to escape plateaus
                shift = self.rng.uniform(-0.25, 0.25, (n_pop, 6))
                pop[:, 18:] = np.clip(pop[:, 18:] + shift, -1.0, 1.0)
                fitness = np.array([self._evaluate(p, func) for p in pop])

            grad_w *= 0.97

        # Phase 2: High-Precision Gradient Refinement
        if self.evals < self.budget * 0.95 and grad_func:
            top_idx = np.argsort(fitness)[:min(3, n_pop)]
            for idx in top_idx:
                if self.evals >= self.budget: break
                x0 = pop[idx]
                cats = x0[18:]
                cont = x0[:18]

                def cost_wrap(x_c): 
                    return self._evaluate(np.concatenate([x_c, cats]), func)
                def grad_wrap(x_c):
                    full = np.concatenate([x_c, cats])
                    try:
                        g = grad_func(full)
                        return np.nan_to_num(g[:18], nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception:
                        return np.zeros(18)

                res = minimize(cost_wrap, cont, jac=grad_wrap, method='L-BFGS-B',
                               bounds=[(-1.0, 1.0)]*18,
                               options={'maxiter': 200, 'ftol': 1e-9, 'gtol': 1e-8})
                if np.isfinite(res.fun) and res.fun < self.best_f:
                    self.best_f = res.fun
                    self.best_x = np.concatenate([res.x, cats])

        return self.best_f, self.best_x

