class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.random.uniform(-1, 1, dim)
        self.rng = np.random.default_rng(42)
        self.stag = 0
        self.cat_archive = []
        self.cat_div_thresh = 0.3
        self.temp = 1.0
        self.grad_hist = []
        self.loss_window = []

    def _evaluate(self, x, func):
        if self.evals >= self.budget: return float('inf')
        xc = np.clip(x, -1.0, 1.0)
        f = func(xc)
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = xc.copy()
        return f

    def _biased_cat_sample(self, n):
        if len(self.cat_archive) == 0:
            return self.rng.uniform(-1.0, 1.0, (n, 6))

        inv_temp = 1.0 / max(self.temp, 1e-4)
        scores = np.exp(inv_temp * np.linalg.norm(self.cat_archive - self.best_x[18:], axis=1))
        probs = scores / np.sum(scores)

        samples = []
        attempts = 0
        while len(samples) < n and attempts < n * 15:
            idx = self.rng.choice(len(self.cat_archive), p=probs)
            cand = self.cat_archive[idx].copy()

            if len(samples) == 0 or np.all(np.linalg.norm(cand - np.array(samples), axis=1) > self.cat_div_thresh):
                noise = self.rng.normal(0, np.clip(0.15 * self.temp, 0.01, 0.4), 6)
                samples.append(cand + noise)
            attempts += 1

        return np.array(samples) if samples else self.rng.uniform(-1.0, 1.0, (n, 6))

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: return self.best_f, self.best_x

        n_pop = max(12, min(70, self.budget // 3))
        pop = _lhs(n_samples=n_pop, n_dim=24)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
        pop[:, 18:] = self._biased_cat_sample(n_pop)

        fitness = np.array([self._evaluate(p, func) for p in pop])
        valid_mask = np.isfinite(fitness)
        max_gen = min(60, max(6, self.budget // n_pop))

        grad_w = 1.2
        f_scale = 1.0
        p_levy = 0.35

        for gen in range(max_gen):
            if self.evals >= self.budget: break

            f_valid = fitness[valid_mask]
            if len(f_valid) > 2:
                f_mean = np.mean(f_valid)
                imp = 1.0 if gen == 0 else np.mean(f_mean < self.loss_window[-1]) if self.loss_window else True
                improvement_rate = 0.95 if imp > 0.4 else 0.65
                f_scale = np.clip(1.0 - (gen / max_gen)**1.5, 0.12, 1.0)
                CR = np.clip(0.6 + 0.35 * (1.0 - improvement_rate), 0.2, 0.9)
            else:
                CR, f_scale = 0.9, 1.0

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]
            g_bias = np.zeros(24)

            if grad_func and gen % 4 == 0:
                try:
                    g = grad_func(x_best)
                    if g is not None and len(g) == 18:
                        g_c = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                        norm_g = np.linalg.norm(g_c) + 1e-8
                        g_bias[:18] = -(g_c / norm_g) * 0.09 * grad_w
                        self.grad_hist.append(norm_g)
                        if len(self.grad_hist) > 12: self.grad_hist.pop(0)
                        grad_w = np.clip(1.2 / (np.mean(self.grad_hist) + 0.05), 0.6, 2.8)
                except Exception: pass

            for i in range(n_pop):
                if self.evals >= self.budget: break

                idxs = self.rng.choice(n_pop, 3, replace=False)
                while np.any(idxs == i): idxs = self.rng.choice(n_pop, 3, replace=False)

                F = np.clip(self.rng.uniform(0.6, 1.2), 0.25, 1.3) * f_scale
                v = x_best + F * (pop[idxs[0]] - pop[idxs[1]])

                # Levy-Gaussian Hybrid
                if self.rng.random() < p_levy:
                    v += self.rng.standard_cauchy(24) * 0.18 * f_scale
                else:
                    v += self.rng.normal(0, 0.06 * f_scale, 24)

                v += g_bias
                v[18:] += self.rng.normal(0, np.clip(0.09 * self.temp, 0.02, 0.25), 6)

                trial = np.clip(v, -1.0, 1.0)
                f_trial = self._evaluate(trial, func)

                # Gradient-projection cliff recovery
                if np.isinf(f_trial) and self.evals < self.budget:
                    if grad_func:
                        try:
                            g = grad_func(trial)
                            if g is not None:
                                g_c = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                                proj_dir = np.concatenate([g_c, np.zeros(6)])
                                norm_p = np.linalg.norm(proj_dir) + 1e-8
                                step = min(0.35, 1.2 / (norm_p + 1e-8))
                                trial = np.clip(trial - proj_dir * step, -1.0, 1.0)
                                f_trial = self._evaluate(trial, func)
                        except Exception: pass
                    if np.isinf(f_trial) and self.rng.random() < 0.45:
                        trial = np.clip(self.rng.uniform(-1.0, 1.0, 24), -1.0, 1.0)
                        f_trial = self._evaluate(trial, func)

                if np.isfinite(f_trial):
                    delta = fitness[i] - f_trial
                    accept_prob = 1.0 if delta > 0 else np.exp(delta / max(self.temp, 1e-4))
                    if self.rng.random() < accept_prob:
                        pop[i] = trial
                        fitness[i] = f_trial
                        if f_trial < self.best_f:
                            self.best_f = f_trial
                            self.best_x = trial.copy()
                            self.cat_archive.append(trial[18:].copy())
                            if len(self.cat_archive) > 45:
                                self.cat_archive = self.cat_archive[:25]
                        self.temp *= 0.995
                else:
                    self.stag += 1

            self.loss_window.append(np.min(fitness))
            if len(self.loss_window) > 6: self.loss_window.pop(0)
            if len(self.loss_window) > 2 and np.all(np.diff(self.loss_window) > -2e-6):
                self.stag += 1
            else:
                self.stag = 0

            if self.stag > 14:
                self.stag = 0
                self.temp = 1.8
                pop[:, 18:] = self._biased_cat_sample(n_pop)
                pop[:n_pop//2, :18] = self.rng.uniform(-1.0, 1.0, (n_pop//2, 18))
                fitness = np.array([self._evaluate(p, func) for p in pop])

        # Adaptive Quasi-Newton Refinement
        if self.evals < self.budget * 0.80 and grad_func:
            top_idx = np.argsort(fitness)[:min(8, n_pop)]
            for idx in top_idx:
                if self.evals >= self.budget * 0.92: break
                x0_c = pop[idx][:18]
                cats = pop[idx][18:]

                def cost_wrap(x_c): return self._evaluate(np.concatenate([x_c, cats]), func)
                def grad_wrap(x_c):
                    full = np.concatenate([x_c, cats])
                    try:
                        g = grad_func(full)
                        return np.nan_to_num(g[:18], nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception:
                        return np.zeros(18)

                res = minimize(cost_wrap, x0_c, jac=grad_wrap, method='L-BFGS-B',
                               bounds=[(-1.0, 1.0)]*18,
                               options={'maxiter': 400, 'ftol': 1e-12, 'gtol': 1e-10})
                if np.isfinite(res.fun) and res.fun < self.best_f:
                    self.best_f = res.fun
                    self.best_x = np.concatenate([res.x, cats])

        return self.best_f, self.best_x

import numpy as np
from scipy.optimize import minimize

try:
    from pyDOE2 import lhs as _lhs
except ImportError:
    try:
        from scipy.stats import qmc
        def _lhs(n_samples, n_dim):
            return qmc.LatinHypercube(d=n_dim).random(n_samples)
    except ImportError:
