class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)
        self.rng = np.random.default_rng()
        self.archive = []
        self.archive_cap = 60

    def _evaluate(self, x, func):
        if self.evals >= self.budget: return float('inf')
        x = np.clip(x, -1.0, 1.0)
        f = func(x)
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = x.copy()
        return f

    def _project_from_cliff(self, x, func, grad_func):
        if grad_func is None:
            return np.clip(x + self.rng.uniform(-0.15, 0.15, 24), -1.0, 1.0), float('inf')
        try:
            g = grad_func(x)
            if g is not None and len(g) == 18:
                g = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                norm = np.linalg.norm(g)
                if norm > 1e-6:
                    step_dir = -g / norm
                    for step in np.linspace(0.01, 0.25, 15):
                        x_new = np.clip(x + np.concatenate([step_dir * step, np.zeros(6)]), -1.0, 1.0)
                        f_new = self._evaluate(x_new, func)
                        if np.isfinite(f_new): return x_new, f_new
        except Exception: pass
        return np.clip(x + self.rng.uniform(-0.2, 0.2, 24), -1.0, 1.0), float('inf')

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: return self.best_f, self.best_x

        n_pop = max(15, min(50, self.budget // 2))
        pop = _lhs(n_samples=n_pop, n_dim=24)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
        fitness = np.array([self._evaluate(p, func) for p in pop])

        max_gen = max(4, min(40, self.budget // n_pop))
        t = 0.0

        for gen in range(max_gen):
            if self.evals >= self.budget: break
            t = gen / max_gen

            f_valid = fitness[np.isfinite(fitness)]
            f_var = np.var(f_valid) if len(f_valid) > 1 else 1e-6
            pop_var = np.var(pop, axis=0)
            diversity_ratio = np.mean(pop_var[:18]) / (np.std(f_valid) + 1e-9)

            # Adaptive mutation parameters
            F = np.clip(0.3 + 0.4 * (1.0 - f_var / (np.abs(f_valid).max() + 1e-9)), 0.1, 0.9)
            gamma = np.clip(1.0 - diversity_ratio * 0.4, 0.0, 1.0)  # Cauchy weight

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]

            g_bias = np.zeros(18)
            grad_norm = 0.0
            if grad_func:
                try:
                    g = grad_func(x_best)
                    if g is not None and len(g) == 18:
                        g_clean = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                        grad_norm = np.linalg.norm(g_clean)
                        if grad_norm > 1e-8:
                            g_bias = (g_clean / grad_norm) * (0.04 * (1.0 - t) + 0.02)
                except Exception: pass

            for i in range(n_pop):
                if self.evals >= self.budget: break
                idxs = self.rng.choice(n_pop, 3, replace=False)
                while i in idxs: idxs = self.rng.choice(n_pop, 3, replace=False)

                # Hybrid Gaussian-Cauchy + DE mutation
                mut = x_best + F * (pop[idxs[0]] - pop[idxs[1]])
                scale = 0.015 * (1.0 - t) + 0.01
                gaussian_noise = self.rng.normal(0, 1, 24) * scale
                cauchy_noise = self.rng.standard_cauchy(24) * scale * 0.6
                mut += (1.0 - gamma) * gaussian_noise + gamma * cauchy_noise
                mut[:18] += g_bias
                mut = np.clip(mut, -1.0, 1.0)

                CR = np.clip(0.5 + 0.4 * t, 0.5, 0.95)
                cr_mask = self.rng.random(24) < CR
                trial = np.where(cr_mask, mut, pop[i])
                f_trial = self._evaluate(trial, func)

                # Adaptive cliff recovery
                if np.isinf(f_trial) and self.evals < self.budget:
                    trial_r, f_trial_r = self._project_from_cliff(trial, func, grad_func)
                    if np.isfinite(f_trial_r):
                        trial, f_trial = trial_r, f_trial_r
                    else:
                        trial = np.clip(trial + self.rng.uniform(-0.15, 0.15, 24), -1.0, 1.0)
                        f_trial = self._evaluate(trial, func)

                if f_trial < fitness[i]:
                    pop[i] = trial
                    fitness[i] = f_trial
                    if np.isfinite(f_trial):
                        div_metric = np.linalg.norm(trial - x_best) + 1e-9
                        if len(self.archive) < self.archive_cap:
                            self.archive.append((trial.copy(), f_trial, div_metric))
                        else:
                            worst_idx = np.argmin([a[2] for a in self.archive])
                            if div_metric > self.archive[worst_idx][2]:
                                self.archive[worst_idx] = (trial.copy(), f_trial, div_metric)
                else:
                    if len(f_valid) > 5 and np.var(f_valid) < 1e-7 and self.rng.random() < 0.15:
                        ref_idx = self.rng.choice(len(self.archive)) if self.archive else best_idx
                        pop[i] = self.archive[ref_idx][0].copy()
                        fitness[i] = self._evaluate(pop[i], func)

        # Phase 2: Gradient-Refined Local Search
        if self.evals < self.budget * 0.85 and grad_func:
            top_indices = np.argsort(fitness)[:min(3, n_pop)]
            for idx in top_indices:
                if self.evals >= self.budget or np.isinf(fitness[idx]): continue
                x0 = pop[idx]
                cats = x0[18:]
                conts = x0[:18]

                try:
                    g_init = grad_func(np.concatenate([conts, cats]))
                    if g_init is not None and np.linalg.norm(g_init) < 1e-3: continue
                except Exception: continue

                def cost_wrap(x_c): return self._evaluate(np.concatenate([x_c, cats]), func)
                def grad_wrap(x_c):
                    full = np.concatenate([x_c, cats])
                    try:
                        g = grad_func(full)
                        return np.nan_to_num(g[:18], nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception: return np.zeros(18)

                remaining = self.budget - self.evals
                max_iter = min(150, max(30, int(remaining / 3)))
                res = minimize(cost_wrap, conts, jac=grad_wrap, method='L-BFGS-B',
                               bounds=[(-1.0, 1.0)]*18,
                               options={'maxiter': max_iter, 'ftol': 1e-12, 'gtol': 1e-9})
                if np.isfinite(res.fun) and res.fun < self.best_f:
                    self.best_f = res.fun
                    self.best_x = np.concatenate([np.clip(res.x, -1.0, 1.0), cats])

        return self.best_f, self.best_x

import numpy as np
from scipy.optimize import minimize

def _get_lhs():
    try:
        from pyDOE2 import lhs as _lhs
        def lhs(n_samples, n_dim): return _lhs(n_samples, n_dim)
    except ImportError:
        try:
            from scipy.stats import qmc
            def lhs(n_samples, n_dim):
                return qmc.LatinHypercube(d=n_dim).random(n=n_samples)
        except ImportError:
            raise ImportError("pyDOE2 or scipy required")
    return lhs

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)
        self.rng = np.random.default_rng()
        self.cat_archive = []
        self._lhs = _get_lhs()
        self.stagnation_counter = 0
        self.last_best_f = float('inf')
        self.max_stagnation = 12

    def _evaluate(self, x, func):
        if self.evals >= self.budget: return float('inf')
        x = np.asarray(x, dtype=np.float64)
        x = np.clip(x, -1.0, 1.0)
        try:
            f = func(x)
        except Exception:
            f = float('inf')
        if not np.isfinite(f):
            f = float('inf')
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = x.copy()
            self.stagnation_counter = 0
            self.last_best_f = f
        else:
            self.stagnation_counter += 1
        return f

    def _adaptive_cat_sample(self, n):
        if not self.cat_archive or self.evals < self.budget * 0.1:
            return self.rng.uniform(-1.0, 1.0, (n, 6))
        f_vals = np.array([item[1] for item in self.cat_archive])
        valid_mask = np.isfinite(f_vals)
        if not np.any(valid_mask):
            return self.rng.uniform(-1.0, 1.0, (n, 6))
        f_valid = f_vals[valid_mask]
        f_min = np.min(f_valid)
        temp = 0.3 + 0.2 * (self.evals / self.budget)
        weights = np.exp(-(f_valid - f_min) / (np.std(f_valid) + 1e-9 + temp))
        weights /= weights.sum()
        idxs = self.rng.choice(np.where(valid_mask)[0], size=n, p=weights)
        base_cats = np.array([self.cat_archive[i][0] for i in idxs])
        scale = 0.04 * np.exp(-2.0 * self.evals / self.budget) + 0.01
        return base_cats + self.rng.normal(0, scale, (n, 6))

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: return self.best_f, self.best_x

        n_pop = max(12, min(45, self.budget // 3))
        pop = self._lhs(n_samples=n_pop, n_dim=24)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
        pop[:, 18:] = self._adaptive_cat_sample(n_pop)
        fitness = np.array([self._evaluate(p, func) for p in pop])

        max_gen = max(5, min(30, self.budget // n_pop))
        f_div_history = []
        grad_history = []

        for gen in range(max_gen):
            if self.evals >= self.budget: break

            valid_mask_g = np.isfinite(fitness)
            if not np.any(valid_mask_g):
                pop = self._lhs(n_samples=n_pop, n_dim=24)
                pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
                pop[:, 18:] = self._adaptive_cat_sample(n_pop)
                fitness = np.array([self._evaluate(p, func) for p in pop])
                self.stagnation_counter = 0
                continue

            if self.stagnation_counter > self.max_stagnation:
                n_reinit = max(4, n_pop // 4)
                idxs = self.rng.choice(n_pop, n_reinit, replace=False)
                for idx in idxs:
                    pop[idx] = self._lhs(1, 24)[0]
                    pop[idx] = np.clip(pop[idx] * 2.0 - 1.0, -1.0, 1.0)
                    pop[idx, 18:] = self._adaptive_cat_sample(1)[0]
                    fitness[idx] = self._evaluate(pop[idx], func)
                self.stagnation_counter = 0
                valid_mask_g = np.isfinite(fitness)

            valid_fitness = fitness[valid_mask_g]
            f_mean, f_std = np.mean(valid_fitness), np.std(valid_fitness)
            f_div_history.append(f_std / (np.abs(f_mean) + 1e-9))
            if len(f_div_history) > 10: f_div_history.pop(0)
            current_div = np.mean(f_div_history)

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]
            is_best_valid = np.isfinite(fitness[best_idx])

            grad_dir = None
            grad_norm = 0.0
            if grad_func and is_best_valid:
                try:
                    x_full_best = np.concatenate([x_best[:18], x_best[18:]])
                    g = grad_func(x_full_best)
                    if g is not None and len(g) == 18:
                        g_clean = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                        grad_norm = np.linalg.norm(g_clean)
                        if grad_norm > 1e-12:
                            grad_dir = g_clean / grad_norm
                            grad_history.append(grad_norm)
                            if len(grad_history) > 8: grad_history.pop(0)
                except Exception: pass

            imp = max(0.0, self.last_best_f - self.best_f)
            alpha_grad = 0.0
            if grad_history and is_best_valid:
                avg_grad = np.mean(grad_history)
                alpha_grad = np.clip(imp * 2.5 / (avg_grad + 1e-9), 0.0, 0.25)

            base_F = 0.4 + 0.4 * current_div
            F = np.clip(base_F, 0.3, 1.0)
            CR = np.clip(0.6 + 0.1 * current_div, 0.6, 0.95)

            for i in range(n_pop):
                if self.evals >= self.budget: break

                idxs = self.rng.choice(n_pop, 3, replace=False)
                while len(set(idxs).intersection({i})) > 0:
                    idxs = self.rng.choice(n_pop, 3, replace=False)

                v = x_best.copy()
                diff = pop[idxs[1]] - pop[idxs[2]]
                mut_scale = F * (1.0 + self.rng.standard_normal() * 0.05)
                v[:18] += mut_scale * diff[:18]
                v[18:] += mut_scale * diff[18:]

                if grad_dir is not None and is_best_valid:
                    v[:18] += alpha_grad * grad_dir

                v = np.clip(v, -1.0, 1.0)

                cr_mask = self.rng.random(24) < CR
                trial = np.where(cr_mask, v, pop[i])
                trial = np.clip(trial, -1.0, 1.0)

                f_trial = self._evaluate(trial, func)

                if np.isinf(f_trial) and self.evals < self.budget and grad_dir is not None and is_best_valid:
                    step = 0.15 * np.maximum(1.0 - self.evals/self.budget, 0.1)
                    x_proj = x_best.copy()
                    x_proj[:18] = np.clip(x_best[:18] - step * grad_dir, -1.0, 1.0)
                    f_proj = self._evaluate(x_proj, func)
                    if np.isfinite(f_proj):
                        trial = x_proj
                        f_trial = f_proj
                    else:
                        trial = self._lhs(1, 24)[0]
                        trial = np.clip(trial * 2.0 - 1.0, -1.0, 1.0)
                        trial[18:] = self._adaptive_cat_sample(1)[0]
                        f_trial = self._evaluate(trial, func)

                if f_trial < fitness[i] or (not np.isfinite(fitness[i]) and np.isfinite(f_trial)):
                    pop[i] = trial
                    fitness[i] = f_trial
                    if np.isfinite(f_trial):
                        new_cat = trial[18:].copy()
                        if not any(np.allclose(c, new_cat, atol=0.05) for c, _ in self.cat_archive):
                            self.cat_archive.append((new_cat, f_trial))
                            if len(self.cat_archive) > 30: self.cat_archive.pop(0)

            # Periodic Micro-Local Search
            if gen % 3 == 0 and grad_func and self.evals < self.budget * 0.80:
                top_k = min(3, np.sum(valid_mask_g))
                if top_k > 0:
                    top_indices = np.argsort(fitness)[:top_k]
                    for idx in top_indices:
                        if self.evals >= self.budget: break
                        if not np.isfinite(fitness[idx]): continue
                        x0_c, x0_cat = pop[idx][:18].copy(), pop[idx][18:].copy()

                        def cost_wrap(x_c):
                            if self.evals >= self.budget: return float('inf')
                            return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat]), func)

                        def grad_wrap(x_c):
                            if self.evals >= self.budget: return np.zeros(18)
                            x_full = np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat])
                            try:
                                g = grad_func(x_full)
                                return np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                            except Exception: return np.zeros(18)

                        rem = max(5, min(25, int((self.budget - self.evals) * 0.3)))
                        try:
                            res = minimize(cost_wrap, x0_c, jac=grad_wrap, method='L-BFGS-B',
                                           bounds=[(-1.0, 1.0)]*18,
                                           options={'maxfun': rem, 'ftol': 1e-10, 'gtol': 1e-10})
                            if np.isfinite(res.fun) and res.fun < fitness[idx]:
                                pop[idx] = np.concatenate([np.clip(res.x, -1.0, 1.0), x0_cat])
                                fitness[idx] = res.fun
                                if res.fun < self.best_f:
                                    self.best_f = res.fun
                                    self.best_x = pop[idx].copy()
                        except Exception: pass

        # Final fallback local search
        if self.evals < self.budget * 0.92 and grad_func:
            valid_indices = np.where(np.isfinite(fitness))[0]
            if len(valid_indices) > 0:
                best_idx = valid_indices[np.argmin(fitness[valid_indices])]
                x0 = pop[best_idx]
                x0_c, x0_cat = x0[:18].copy(), x0[18:].copy()

                def cost_wrap(x_c):
                    if self.evals >= self.budget: return float('inf')
                    return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat]), func)

                def grad_wrap(x_c):
                    if self.evals >= self.budget: return np.zeros(18)
                    x_full = np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat])
                    try:
                        g = grad_func(x_full)
                        return np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception: return np.zeros(18)

                rem = max(10, min(50, int((self.budget - self.evals) * 0.3)))
                try:
                    res = minimize(cost_wrap, x0_c, jac=grad_wrap, method='L-BFGS-B',
                                   bounds=[(-1.0, 1.0)]*18,
                                   options={'maxfun': rem, 'ftol': 1e-12, 'gtol': 1e-10})
                    if np.isfinite(res.fun) and res.fun < self.best_f:
                        self.best_f = res.fun
                        self.best_x = np.concatenate([np.clip(res.x, -1.0, 1.0), x0_cat])
                except Exception: pass

        return self.best_f, self.best_x

import numpy as np
from scipy.optimize import minimize

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)
        self.rng = np.random.default_rng()
        self.cat_archive = []
        self._get_lhs()
        self.last_best_idx = -1
        self.g_bias_cont = np.zeros(18)
        self.grad_norm = 1e-12

    def _get_lhs(self):
        try:
            from pyDOE2 import lhs as _lhs
            def lhs(n_samples, n_dim): return _lhs(n_samples, n_dim)
        except ImportError:
            try:
                from scipy.stats import qmc
                def lhs(n_samples, n_dim):
                    return qmc.LatinHypercube(d=n_dim).random(n=n_samples)
            except ImportError:
                raise ImportError("pyDOE2 or scipy required")
        self._lhs = lhs

    def _evaluate(self, x, func):
        if self.evals >= self.budget: return float('inf')
        x = np.clip(x, -1.0, 1.0)
        f = func(x)
        self.evals += 1
        if np.isfinite(f) and f < self.best_f:
            self.best_f = f
            self.best_x = x.copy()
            self.last_best_idx = -1  # Force gradient recomputation on improvement
        return f

    def _monotonic_cat_sample(self, n, gen, max_gen):
        # Strictly monotonic temperature decay prevents oscillation
        temp = 1.0 * np.exp(-2.0 * (gen / max_gen))
        if not self.cat_archive:
            return self.rng.uniform(-1.0, 1.0, (n, 6))
        f_vals = np.array([item[1] for item in self.cat_archive])
        valid_mask = np.isfinite(f_vals)
        if not np.any(valid_mask):
            return self.rng.uniform(-1.0, 1.0, (n, 6))
        f_valid = f_vals[valid_mask]
        f_min = np.min(f_valid)
        f_shifted = np.clip(f_valid - f_min, 0, None)
        weights = np.exp(-f_shifted / (np.std(f_valid) + 1e-9 + temp))
        weights /= weights.sum()
        idxs = self.rng.choice(np.where(valid_mask)[0], size=n, p=weights)
        base_cats = np.array([self.cat_archive[i][0] for i in idxs])
        scale = 0.08 * np.clip(1.0 - gen/max_gen, 0.1, 1.0)
        return base_cats + self.rng.normal(0, scale, (n, 6))

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: return self.best_f, self.best_x

        n_pop = max(10, min(40, self.budget // 4))
        pop = self._lhs(n_samples=n_pop, n_dim=24)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
        pop[:, 18:] = self._monotonic_cat_sample(n_pop, 0, 1)
        fitness = np.array([self._evaluate(p, func) for p in pop])

        max_gen = max(5, min(30, self.budget // n_pop))
        for gen in range(max_gen):
            if self.evals >= self.budget: break
            t_frac = 1.0 - (gen / max_gen)

            valid_mask_g = np.isfinite(fitness)
            if not np.any(valid_mask_g):
                pop = self._lhs(n_samples=n_pop, n_dim=24)
                pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
                pop[:, 18:] = self._monotonic_cat_sample(n_pop, gen, max_gen)
                fitness = np.array([self._evaluate(p, func) for p in pop])
                continue

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]

            # Recompute gradient guidance only when the global best changes
            if grad_func and np.isfinite(fitness[best_idx]) and self.last_best_idx != best_idx:
                self.last_best_idx = best_idx
                try:
                    full_best = np.concatenate([x_best[:18], x_best[18:]])
                    g = grad_func(full_best)
                    if g is not None and len(g) == 18:
                        g_clean = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                        g_norm = np.linalg.norm(g_clean)
                        if g_norm > 1e-10:
                            self.g_bias_cont = g_clean / g_norm
                            self.grad_norm = g_norm
                        else:
                            self.g_bias_cont = np.zeros(18)
                            self.grad_norm = 1e-12
                    else:
                        self.g_bias_cont = np.zeros(18)
                        self.grad_norm = 1e-12
                except Exception:
                    self.g_bias_cont = np.zeros(18)
                    self.grad_norm = 1e-12

            for i in range(n_pop):
                if self.evals >= self.budget: break

                F = 0.5 + 0.5 * t_frac + 0.1 * self.rng.random()
                cr_mask = np.full(24, False)
                cr_mask[:18] = self.rng.random(18) < (0.9 * t_frac + 0.1)
                cr_mask[18:] = self.rng.random(6) < (0.3 * t_frac + 0.1)

                idxs = self.rng.choice(n_pop, 3, replace=False)
                while i in idxs: idxs = self.rng.choice(n_pop, 3, replace=False)

                v = x_best + F * (pop[idxs[0]] - pop[idxs[1]])
                v[:18] += self.g_bias_cont * 0.1 * t_frac  # Normalized gradient guidance

                v = np.clip(v, -1.0, 1.0)
                trial = np.where(cr_mask, v, pop[i])

                # Adaptive noise injection
                trial[:18] += self.rng.normal(0, 0.02 * t_frac + 0.005, 18)
                trial[18:] += self.rng.normal(0, 0.05 * t_frac + 0.01, 6)
                trial = np.clip(trial, -1.0, 1.0)

                f_trial = self._evaluate(trial, func)

                # Robust cliff recovery using normalized gradient backtracking
                if np.isinf(f_trial) and self.evals < self.budget:
                    if self.grad_norm > 1e-10:
                        step_back = 0.3 * t_frac
                        x_recover = x_best.copy()
                        x_recover[:18] = np.clip(x_best[:18] - step_back * self.g_bias_cont, -1.0, 1.0)
                        x_recover[18:] = x_best[18:] + self.rng.normal(0, 0.05, 6)
                        f_recover = self._evaluate(x_recover, func)
                        if np.isfinite(f_recover):
                            f_trial = f_recover
                            trial = x_recover

                # Fallback to LHS if cliff persists
                if np.isinf(f_trial):
                    resamp = self._lhs(1, 24)[0]
                    resamp = np.clip(resamp * 2.0 - 1.0, -1.0, 1.0)
                    resamp[18:] = self._monotonic_cat_sample(1, gen, max_gen)[0]
                    f_trial = self._evaluate(resamp, func)
                    trial = resamp

                if f_trial < fitness[i] or (not np.isfinite(fitness[i]) and np.isfinite(f_trial)):
                    pop[i] = trial
                    fitness[i] = f_trial
                    if np.isfinite(f_trial):
                        new_cat = trial[18:].copy()
                        if not any(np.allclose(c, new_cat, atol=0.1) for c, _ in self.cat_archive):
                            self.cat_archive.append((new_cat, f_trial))
                            if len(self.cat_archive) > 30: self.cat_archive.pop(0)

        # Strict L-BFGS-B exploitation phase
        if self.evals < self.budget * 0.85 and grad_func:
            valid_indices = np.where(np.isfinite(fitness))[0]
            if len(valid_indices) > 0:
                best_idx_lb = valid_indices[np.argmin(fitness[valid_indices])]
                x0_lb = pop[best_idx_lb]
                cats_lb = x0_lb[18:].copy()
                conts_lb = x0_lb[:18].copy()

                def cost_wrap(x_c):
                    if self.evals >= self.budget: return float('inf')
                    return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), cats_lb]), func)

                def grad_wrap(x_c):
                    full = np.concatenate([np.clip(x_c, -1.0, 1.0), cats_lb])
                    try:
                        g = grad_func(full)
                        return np.nan_to_num(g[:18], nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception: return np.zeros(18)

                remaining = max(10, int((self.budget - self.evals) * 0.15))
                try:
                    res = minimize(cost_wrap, conts_lb, jac=grad_wrap, method='L-BFGS-B',
                                   bounds=[(-1.0, 1.0)]*18,
                                   options={'maxiter': min(50, remaining), 'ftol': 1e-14, 'gtol': 1e-12})
                    if np.isfinite(res.fun) and res.fun < self.best_f:
                        self.best_f = res.fun
                        self.best_x = np.concatenate([np.clip(res.x, -1.0, 1.0), cats_lb])
                except Exception: pass

        return self.best_f, self.best_x

import numpy as np
from scipy.optimize import minimize

def _get_lhs():
    try:
        from pyDOE2 import lhs as _lhs
        return lambda n, d: _lhs(n, d)
    except ImportError:
        try:
            from scipy.stats import qmc
            return lambda n, d: qmc.LatinHypercube(d=d).random(n=n)
        except ImportError:
            raise ImportError("pyDOE2 or scipy required")

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)
        self.rng = np.random.default_rng()
        self._lhs = _get_lhs()

    def _evaluate(self, x, func):
        if self.evals >= self.budget:
            return float('inf')
        x = np.clip(x, -1.0, 1.0)
        f = func(x)
        self.evals += 1
        if np.isfinite(f) and f < self.best_f:
            self.best_f = f
            self.best_x = x.copy()
        return f

    def _adaptive_levy(self, dim):
        u = self.rng.normal(0, 1, dim)
        v = self.rng.normal(0, 1, dim)
        return u / (np.abs(v) ** 0.5) * 1.5

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget:
            return self.best_f, self.best_x

        n_pop = max(15, min(45, self.budget // 4))
        pop = self._lhs(n_samples=n_pop, n_dim=24) * 2.0 - 1.0
        pop = np.clip(pop, -1.0, 1.0)
        fitness = np.array([self._evaluate(p, func) for p in pop])

        max_gen = max(8, min(35, self.budget // n_pop))
        diversity_threshold = 0.08

        for gen in range(max_gen):
            if self.evals >= self.budget:
                break
            t_frac = 1.0 - gen / max_gen

            # Diversity monitoring & automatic rejuvenation
            pop_range = np.ptp(pop, axis=0)
            current_div = np.mean(pop_range)
            if current_div < diversity_threshold and gen > max_gen // 3:
                n_rej = n_pop // 2
                idxs = self.rng.choice(n_pop, n_rej, replace=False)
                pop[idxs] = self._lhs(n_samples=n_rej, n_dim=24) * 2.0 - 1.0
                pop = np.clip(pop, -1.0, 1.0)
                fitness[idxs] = np.array([self._evaluate(p, func) for p in pop[idxs]])

            valid_mask = np.isfinite(fitness)
            if not np.any(valid_mask):
                pop = self._lhs(n_samples=n_pop, n_dim=24) * 2.0 - 1.0
                pop = np.clip(pop, -1.0, 1.0)
                fitness = np.array([self._evaluate(p, func) for p in pop])
                continue

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]
            is_best_valid = np.isfinite(fitness[best_idx])

            # Gradient guidance recomputed periodically with variance scaling
            g_bias = np.zeros(24)
            grad_norm = 0.0
            if grad_func and is_best_valid and gen % 4 == 0:
                try:
                    full_best = np.concatenate([x_best[:18], x_best[18:]])
                    g = grad_func(full_best)
                    if g is not None and len(g) == 18:
                        g_clean = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                        grad_norm = np.linalg.norm(g_clean)
                        if grad_norm > 1e-10:
                            # Scale steps by population spread per dimension
                            dim_scale = np.maximum(np.ptp(pop, axis=0), 0.05)
                            step_magnitudes = 0.25 * dim_scale
                            g_bias[:18] = np.clip((g_clean / grad_norm) * step_magnitudes[:18], -0.25, 0.25)
                except Exception:
                    pass

            for i in range(n_pop):
                if self.evals >= self.budget:
                    break
                idxs = self.rng.choice(n_pop, 3, replace=False)
                while i in idxs:
                    idxs = self.rng.choice(n_pop, 3, replace=False)

                # Hybrid DE + Levy mutation
                levy_prob = 0.2 * t_frac + 0.05
                if self.rng.random() < levy_prob:
                    v = x_best + 0.7 * self._adaptive_levy(24)
                else:
                    F = 0.4 + 0.6 * t_frac
                    v = x_best + F * (pop[idxs[0]] - pop[idxs[1]])

                v = np.clip(v, -1.0, 1.0)

                # Block-aware crossover
                cr = self.rng.random(24)
                cr[:18] = cr[:18] < (0.85 * t_frac + 0.15)
                cr[18:] = cr[18:] < (0.30 * t_frac + 0.10)
                trial = np.where(cr, v, pop[i])

                # Gradient perturbation
                if grad_norm > 1e-10 and self.rng.random() < 0.15:
                    trial[:18] += g_bias[:18] * 0.4

                trial = np.clip(trial, -1.0, 1.0)
                f_trial = self._evaluate(trial, func)

                # Intelligent cliff recovery
                if np.isinf(f_trial) and is_best_valid and grad_norm > 1e-10:
                    x_recovery = x_best.copy()
                    x_recovery[:18] = np.clip(x_best[:18] - g_bias[:18] * 2.0, -1.0, 1.0)
                    f_rec = self._evaluate(x_recovery, func)
                    if np.isfinite(f_rec):
                        trial, f_trial = x_recovery, f_rec
                    else:
                        trial = self._lhs(n_samples=1, n_dim=24)[0] * 2.0 - 1.0
                        trial = np.clip(trial, -1.0, 1.0)
                        f_trial = self._evaluate(trial, func)

                if f_trial < fitness[i] or (not np.isfinite(fitness[i]) and np.isfinite(f_trial)):
                    pop[i], fitness[i] = trial, f_trial

        # Dynamic L-BFGS exploitation (only if convergence confirmed & budget remains)
        if self.evals < self.budget * 0.85 and grad_func:
            valid_indices = np.where(np.isfinite(fitness))[0]
            if len(valid_indices) > 0:
                best_idx = valid_indices[np.argmin(fitness[valid_indices])]
                x0 = pop[best_idx]
                cats = x0[18:].copy()
                conts = x0[:18].copy()

                try:
                    full_x0 = np.concatenate([conts, cats])
                    g_init = grad_func(full_x0)
                    if g_init is None:
                        raise ValueError("Gradient missing")
                    g_init = np.nan_to_num(g_init, nan=0.0, posinf=0.0, neginf=0.0)
                except Exception:
                    return self.best_f, self.best_x

                def cost_wrap(x_c):
                    if self.evals >= self.budget:
                        return float('inf')
                    return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), cats]), func)

                def grad_wrap(x_c):
                    full = np.concatenate([np.clip(x_c, -1.0, 1.0), cats])
                    try:
                        g = grad_func(full)
                        return np.nan_to_num(g[:18], nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception:
                        return np.zeros(18)

                remaining = self.budget - self.evals
                max_iter = int(np.clip(remaining * 0.15, 10, 80))
                try:
                    res = minimize(cost_wrap, conts, jac=grad_wrap, method='L-BFGS-B',
                                   bounds=[(-1.0, 1.0)] * 18,
                                   options={'maxiter': max_iter, 'ftol': 1e-12, 'gtol': 1e-10, 'maxls': 50})
                    if np.isfinite(res.fun) and res.fun < self.best_f:
                        self.best_f = res.fun
                        self.best_x = np.concatenate([np.clip(res.x, -1.0, 1.0), cats])
                except Exception:
                    pass

        return self.best_f, self.best_x

import numpy as np
from scipy.optimize import minimize

def _get_lhs():
    try:
        from pyDOE2 import lhs as _lhs
        def lhs(n_samples, n_dim): return _lhs(n_samples, n_dim)
    except ImportError:
        try:
            from scipy.stats import qmc
            def lhs(n_samples, n_dim):
                return qmc.LatinHypercube(d=n_dim).random(n=n_samples)
        except ImportError:
            raise ImportError("pyDOE2 or scipy required")
    return lhs

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)
        self.rng = np.random.default_rng()
        self.cat_regions = []
        self._lhs = _get_lhs()
        self.stagnation_counter = 0
        self.last_best_f = float('inf')
        self.max_stagnation = 15
        self.cliff_history = []

    def _evaluate(self, x, func):
        if self.evals >= self.budget: return float('inf')
        x = np.asarray(x, dtype=np.float64)
        x = np.clip(x, -1.0, 1.0)
        try:
            f = func(x)
        except Exception:
            f = float('inf')
        if not np.isfinite(f):
            f = float('inf')
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = x.copy()
            self.stagnation_counter = 0
            self.last_best_f = f
            self.cliff_history = []
        else:
            self.stagnation_counter += 1
            if np.isinf(f):
                self.cliff_history.append(self.evals)
        return f

    def _stratified_cat_sample(self, n):
        use_clusters = len(self.cat_regions) > 2 and self.rng.random() < 0.65
        if use_clusters:
            idx = self.rng.integers(len(self.cat_regions))
            center, radius = self.cat_regions[idx]
            samples = center + self.rng.normal(0, radius * 0.4, (n, 6))
            if self.rng.random() < 0.3:
                idx2 = self.rng.integers(len(self.cat_regions))
                center2, radius2 = self.cat_regions[idx2]
                samples[self.rng.integers(n)] = center2 + self.rng.normal(0, radius2 * 0.2, (1, 6))
            return np.clip(samples, -1.0, 1.0)
        return self.rng.uniform(-1.0, 1.0, (n, 6))

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: return self.best_f, self.best_x

        n_pop = max(15, min(50, self.budget // 2))
        pop = self._lhs(n_samples=n_pop, n_dim=24)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
        pop[:, 18:] = self._stratified_cat_sample(n_pop)
        fitness = np.array([self._evaluate(p, func) for p in pop])

        max_gen = max(6, min(25, self.budget // n_pop))
        f_div_history = []
        grad_norm_history = []
        local_search_budget = 0

        for gen in range(max_gen):
            if self.evals >= self.budget: break

            valid_mask = np.isfinite(fitness)
            if not np.any(valid_mask):
                pop = self._lhs(n_samples=n_pop, n_dim=24)
                pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
                pop[:, 18:] = self._stratified_cat_sample(n_pop)
                fitness = np.array([self._evaluate(p, func) for p in pop])
                self.stagnation_counter = 0
                continue

            valid_fit = fitness[valid_mask]
            f_mean, f_std = np.mean(valid_fit), np.std(valid_fit)
            f_div = f_std / (np.abs(f_mean) + 1e-9)
            f_div_history.append(f_div)
            if len(f_div_history) > 10: f_div_history.pop(0)
            current_div = np.mean(f_div_history)

            if self.stagnation_counter > self.max_stagnation or current_div < 0.06:
                n_reinit = max(5, n_pop // 3)
                idxs = self.rng.choice(n_pop, n_reinit, replace=False)
                for idx in idxs:
                    pop[idx] = self._lhs(1, 24)[0]
                    pop[idx] = np.clip(pop[idx] * 2.0 - 1.0, -1.0, 1.0)
                    pop[idx, 18:] = self._stratified_cat_sample(1)[0]
                    fitness[idx] = self._evaluate(pop[idx], func)
                self.stagnation_counter = 0
                f_div_history = []

            # Ensemble Gradient Guidance (Top 20%)
            grad_dir = None
            grad_norm = 0.0
            top_k = max(1, int(n_pop * 0.2))
            if grad_func:
                try:
                    valid_indices = np.where(valid_mask)[0]
                    top_indices = valid_indices[np.argsort(fitness[valid_indices])[:top_k]]
                    grad_accum = np.zeros(18)
                    for idx in top_indices:
                        g = grad_func(pop[idx])
                        if g is not None and len(g) == 18:
                            grad_accum += np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                    if np.any(grad_accum):
                        grad_accum /= len(top_indices)
                        grad_norm = np.linalg.norm(grad_accum)
                        if grad_norm > 1e-12:
                            grad_dir = grad_accum / grad_norm
                            grad_norm_history.append(grad_norm)
                            if len(grad_norm_history) > 8: grad_norm_history.pop(0)
                except Exception: pass

            # Adaptive Mutation Parameters
            base_F = 0.4 + 0.6 * (1.0 - current_div)
            recent_cliffs = len([t for t in self.cliff_history if self.evals - t < 5])
            F = np.clip(base_F + 0.35 * recent_cliffs, 0.4, 1.3)
            CR = np.clip(0.5 + 0.3 * current_div, 0.5, 0.9)

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]
            is_best_valid = np.isfinite(fitness[best_idx])

            alpha_grad = 0.0
            if grad_dir is not None and is_best_valid and len(grad_norm_history) > 0:
                imp = max(0.0, self.last_best_f - self.best_f)
                avg_g = np.mean(grad_norm_history)
                alpha_grad = np.clip(imp * 3.0 / (avg_g + 1e-9), 0.0, 0.3)

            for i in range(n_pop):
                if self.evals >= self.budget: break

                idxs = self.rng.choice(n_pop, 3, replace=False)
                while len(set(idxs).intersection({i})) > 0:
                    idxs = self.rng.choice(n_pop, 3, replace=False)

                v = x_best.copy()
                diff = pop[idxs[1]] - pop[idxs[2]]
                mut_scale = F * (1.0 + self.rng.standard_normal() * 0.08)
                v[:18] += mut_scale * diff[:18]
                v[18:] += mut_scale * diff[18:]

                if grad_dir is not None and is_best_valid:
                    v[:18] += alpha_grad * grad_dir

                v = np.clip(v, -1.0, 1.0)
                cr_mask = self.rng.random(24) < CR
                trial = np.where(cr_mask, v, pop[i])
                trial = np.clip(trial, -1.0, 1.0)

                f_trial = self._evaluate(trial, func)

                # Cliff-reactive recovery
                if np.isinf(f_trial) and self.evals < self.budget:
                    step_size = 0.25 * (1.0 - self.evals/self.budget) + 0.05
                    x_expl = x_best.copy()
                    if grad_dir is not None:
                        x_expl[:18] -= step_size * grad_dir
                    else:
                        x_expl[:18] += step_size * self.rng.normal(0, 1, 18)
                    x_expl = np.clip(x_expl, -1.0, 1.0)
                    f_expl = self._evaluate(x_expl, func)
                    if np.isfinite(f_expl) and f_expl < self.best_f * 1.1:
                        trial = x_expl
                        f_trial = f_expl
                    else:
                        trial = self._lhs(1, 24)[0]
                        trial = np.clip(trial * 2.0 - 1.0, -1.0, 1.0)
                        trial[18:] = self._stratified_cat_sample(1)[0]
                        f_trial = self._evaluate(trial, func)

                if f_trial < fitness[i] or (not np.isfinite(fitness[i]) and np.isfinite(f_trial)):
                    pop[i] = trial
                    fitness[i] = f_trial
                    if np.isfinite(f_trial):
                        center = trial[18:]
                        if self.cat_regions:
                            dists = [np.linalg.norm(c - center) for c, _ in self.cat_regions]
                            min_idx = np.argmin(dists)
                            if dists[min_idx] < 0.3:
                                c, r = self.cat_regions[min_idx]
                                self.cat_regions[min_idx] = (0.9*c + 0.1*center, r*0.95)
                            else:
                                self.cat_regions.append((center.copy(), 0.2))
                        else:
                            self.cat_regions.append((center.copy(), 0.2))
                        if len(self.cat_regions) > 10: self.cat_regions.pop(0)

            # Budget-Aware Local Search Trigger
            local_budget_alloc = int((self.budget - self.evals) * 0.15)
            if local_budget_alloc > 10 and current_div < 0.12 and grad_func:
                top_indices = np.argsort(fitness)[:min(2, np.sum(valid_mask))]
                for idx in top_indices:
                    if self.evals >= self.budget or local_search_budget >= local_budget_alloc: break
                    if not np.isfinite(fitness[idx]): continue

                    x0_c, x0_cat = pop[idx][:18].copy(), pop[idx][18:].copy()
                    alloc = max(5, min(20, local_budget_alloc - local_search_budget))

                    def cost_wrap(x_c):
                        if self.evals >= self.budget: return float('inf')
                        return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat]), func)
                    def grad_wrap(x_c):
                        if self.evals >= self.budget: return np.zeros(18)
                        x_full = np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat])
                        try:
                            g = grad_func(x_full)
                            return np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                        except Exception: return np.zeros(18)

                    try:
                        res = minimize(cost_wrap, x0_c, jac=grad_wrap, method='L-BFGS-B',
                                       bounds=[(-1.0, 1.0)]*18,
                                       options={'maxfun': alloc, 'ftol': 1e-10, 'gtol': 1e-10})
                        if np.isfinite(res.fun) and res.fun < fitness[idx]:
                            pop[idx] = np.concatenate([np.clip(res.x, -1.0, 1.0), x0_cat])
                            fitness[idx] = res.fun
                            local_search_budget += alloc
                            if res.fun < self.best_f:
                                self.best_f = res.fun
                                self.best_x = pop[idx].copy()
                    except Exception: pass

        if self.evals < self.budget * 0.95 and grad_func:
            valid_indices = np.where(np.isfinite(fitness))[0]
            if len(valid_indices) > 0:
                best_idx = valid_indices[np.argmin(fitness[valid_indices])]
                x0 = pop[best_idx]
                x0_c, x0_cat = x0[:18].copy(), x0[18:].copy()
                def cost_wrap(x_c):
                    if self.evals >= self.budget: return float('inf')
                    return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat]), func)
                def grad_wrap(x_c):
                    if self.evals >= self.budget: return np.zeros(18)
                    x_full = np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat])
                    try:
                        g = grad_func(x_full)
                        return np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception: return np.zeros(18)
                rem = max(10, min(40, int((self.budget - self.evals) * 0.2)))
                try:
                    res = minimize(cost_wrap, x0_c, jac=grad_wrap, method='L-BFGS-B',
                                   bounds=[(-1.0, 1.0)]*18,
                                   options={'maxfun': rem, 'ftol': 1e-12, 'gtol': 1e-10})
                    if np.isfinite(res.fun) and res.fun < self.best_f:
                        self.best_f = res.fun
                        self.best_x = np.concatenate([np.clip(res.x, -1.0, 1.0), x0_cat])
                except Exception: pass

        return self.best_f, self.best_x

import numpy as np
from scipy.optimize import minimize

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)
        self.rng = np.random.default_rng()
        self.cat_archive = []
        self._get_lhs()
        self.last_best_idx = -1
        self.g_bias_cont = np.zeros(18)
        self.grad_norm = 1e-12
        self.last_grad_update_gen = -1

    def _get_lhs(self):
        try:
            from pyDOE2 import lhs as _lhs
            def lhs(n_samples, n_dim): return _lhs(n_samples, n_dim)
        except ImportError:
            try:
                from scipy.stats import qmc
                def lhs(n_samples, n_dim):
                    return qmc.LatinHypercube(d=n_dim).random(n=n_samples)
            except ImportError:
                raise ImportError("pyDOE2 or scipy required")
        self._lhs = lhs

    def _evaluate(self, x, func):
        if self.evals >= self.budget: return float('inf')
        x = np.clip(x, -1.0, 1.0)
        f = func(x)
        self.evals += 1
        if np.isfinite(f) and f < self.best_f:
            self.best_f = f
            self.best_x = x.copy()
            self.last_best_idx = -1
        return f

    def _monotonic_cat_sample(self, n, gen, max_gen):
        temp = 1.0 * np.exp(-2.0 * (gen / max_gen))
        if not self.cat_archive:
            return self.rng.uniform(-1.0, 1.0, (n, 6))
        f_vals = np.array([item[1] for item in self.cat_archive])
        valid_mask = np.isfinite(f_vals)
        if not np.any(valid_mask):
            return self.rng.uniform(-1.0, 1.0, (n, 6))
        f_valid = f_vals[valid_mask]
        f_min = np.min(f_valid)
        f_shifted = np.clip(f_valid - f_min, 0, None)
        weights = np.exp(-f_shifted / (np.std(f_valid) + 1e-9 + temp))
        weights /= weights.sum()
        idxs = self.rng.choice(np.where(valid_mask)[0], size=min(n, len(np.where(valid_mask)[0])), p=weights)
        base_cats = np.array([self.cat_archive[i][0] for i in idxs])
        scale = 0.06 * np.clip(1.0 - gen/max_gen, 0.1, 1.0)
        return base_cats + self.rng.normal(0, scale, (n, 6))

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: return self.best_f, self.best_x

        n_pop = max(10, min(40, self.budget // 4))
        pop = self._lhs(n_samples=n_pop, n_dim=24)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
        pop[:, 18:] = self._monotonic_cat_sample(n_pop, 0, 1)
        fitness = np.array([self._evaluate(p, func) for p in pop])

        max_gen = max(5, min(30, self.budget // n_pop))
        for gen in range(max_gen):
            if self.evals >= self.budget: break
            t_frac = 1.0 - (gen / max_gen)

            valid_mask_g = np.isfinite(fitness)
            if not np.any(valid_mask_g):
                pop = self._lhs(n_samples=n_pop, n_dim=24)
                pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
                pop[:, 18:] = self._monotonic_cat_sample(n_pop, gen, max_gen)
                fitness = np.array([self._evaluate(p, func) for p in pop])
                continue

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]

            # Recompute gradient only on best change OR staleness threshold
            if grad_func and np.isfinite(fitness[best_idx]):
                stale = (gen - self.last_grad_update_gen) > 5
                if self.last_best_idx != best_idx or stale:
                    self.last_best_idx = best_idx
                    self.last_grad_update_gen = gen
                    try:
                        g = grad_func(np.concatenate([x_best[:18], x_best[18:]]))
                        if g is not None and len(g) == 18:
                            g_clean = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                            g_norm = np.linalg.norm(g_clean)
                            if g_norm > 1e-10:
                                self.g_bias_cont = g_clean / g_norm
                                self.grad_norm = g_norm
                            else:
                                self.g_bias_cont = np.zeros(18)
                                self.grad_norm = 1e-12
                        else:
                            self.g_bias_cont = np.zeros(18)
                            self.grad_norm = 1e-12
                    except Exception:
                        self.g_bias_cont = np.zeros(18)
                        self.grad_norm = 1e-12

            # Periodic Micro-Local Search on top valid candidate
            if gen % 3 == 0 and grad_func and self.evals < self.budget * 0.9:
                valid_indices = np.where(np.isfinite(fitness))[0]
                if len(valid_indices) > 0:
                    local_best_idx = valid_indices[np.argmin(fitness[valid_indices])]
                    x0_loc = pop[local_best_idx]
                    cats_loc = x0_loc[18:].copy()
                    conts_loc = x0_loc[:18].copy()
                    micro_evals = 0
                    micro_budget = max(5, int((self.budget - self.evals) * 0.1))
                    def micro_cost_wrap(x_c):
                        nonlocal micro_evals
                        if micro_evals >= micro_budget or self.evals >= self.budget: return float('inf')
                        micro_evals += 1
                        return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), cats_loc]), func)
                    def micro_grad_wrap(x_c):
                        full = np.concatenate([np.clip(x_c, -1.0, 1.0), cats_loc])
                        try:
                            g = grad_func(full)
                            return np.nan_to_num(g[:18], nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                        except: return np.zeros(18)
                    try:
                        res = minimize(micro_cost_wrap, conts_loc, jac=micro_grad_wrap, method='L-BFGS-B',
                                       bounds=[(-1.0, 1.0)]*18, options={'maxiter': max(5, micro_budget//2)})
                        if np.isfinite(res.fun) and res.fun < self.best_f:
                            self.best_f = res.fun
                            self.best_x = np.concatenate([np.clip(res.x, -1.0, 1.0), cats_loc])
                    except: pass

            for i in range(n_pop):
                if self.evals >= self.budget: break
                F = 0.5 + 0.5 * t_frac + 0.1 * self.rng.random()
                cr_mask = np.full(24, False)
                cr_mask[:18] = self.rng.random(18) < (0.9 * t_frac + 0.1)
                cr_mask[18:] = self.rng.random(6) < (0.5 * t_frac + 0.2)
                idxs = self.rng.choice(n_pop, 3, replace=False)
                while i in idxs: idxs = self.rng.choice(n_pop, 3, replace=False)
                v = x_best + F * (pop[idxs[0]] - pop[idxs[1]])
                v[:18] += self.g_bias_cont * 0.1 * t_frac
                v = np.clip(v, -1.0, 1.0)
                trial = np.where(cr_mask, v, pop[i])
                trial[:18] += self.rng.normal(0, 0.015 * t_frac + 0.003, 18)
                trial[18:] += self.rng.normal(0, 0.04 * t_frac + 0.008, 6)
                trial = np.clip(trial, -1.0, 1.0)
                f_trial = self._evaluate(trial, func)

                # Archive-guided stochastic cliff recovery
                if np.isinf(f_trial) and self.evals < self.budget:
                    recover_found = False
                    if len(self.cat_archive) > 0:
                        valid_arch = [(c, f) for c, f in self.cat_archive if np.isfinite(f)]
                        if valid_arch:
                            rec_size = min(5, len(valid_arch))
                            for _ in range(rec_size):
                                if self.evals >= self.budget: break
                                r_idx = self.rng.choice(len(valid_arch))
                                r_x = valid_arch[r_idx][0].copy()
                                r_x[:18] = np.clip(x_best[:18] - 0.2 * self.g_bias_cont + self.rng.normal(0, 0.08, 18), -1, 1)
                                r_x[18:] = r_x[18:] + self.rng.normal(0, 0.04, 6)
                                r_x = np.clip(r_x, -1, 1)
                                f_r = self._evaluate(r_x, func)
                                if np.isfinite(f_r):
                                    f_trial = f_r
                                    trial = r_x
                                    recover_found = True
                                    break
                    if not recover_found:
                        resamp = self._lhs(1, n_dim=24)[0]
                        resamp = np.clip(resamp * 2.0 - 1.0, -1.0, 1.0)
                        resamp[18:] = self._monotonic_cat_sample(1, gen, max_gen)[0]
                        f_trial = self._evaluate(resamp, func)
                        trial = resamp

                if f_trial < fitness[i] or (not np.isfinite(fitness[i]) and np.isfinite(f_trial)):
                    pop[i] = trial
                    fitness[i] = f_trial
                    if np.isfinite(f_trial):
                        if not any(np.allclose(c, trial[18:], atol=0.05) for c, _ in self.cat_archive):
                            self.cat_archive.append((trial[18:].copy(), f_trial))
                            self.cat_archive.sort(key=lambda k: k[1])
                            if len(self.cat_archive) > 100: self.cat_archive.pop()

        # Strict final L-BFGS-B exploitation
        if self.evals < self.budget * 0.85 and grad_func:
            valid_indices = np.where(np.isfinite(fitness))[0]
            if len(valid_indices) > 0:
                best_idx_lb = valid_indices[np.argmin(fitness[valid_indices])]
                x0_lb = pop[best_idx_lb]
                cats_lb = x0_lb[18:].copy()
                conts_lb = x0_lb[:18].copy()
                final_evals = 0
                final_budget = max(10, int((self.budget - self.evals) * 0.15))
                def cost_wrap(x_c):
                    nonlocal final_evals
                    if final_evals >= final_budget or self.evals >= self.budget: return float('inf')
                    final_evals += 1
                    return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), cats_lb]), func)
                def grad_wrap(x_c):
                    full = np.concatenate([np.clip(x_c, -1.0, 1.0), cats_lb])
                    try:
                        g = grad_func(full)
                        return np.nan_to_num(g[:18], nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except: return np.zeros(18)
                try:
                    res = minimize(cost_wrap, conts_lb, jac=grad_wrap, method='L-BFGS-B',
                                   bounds=[(-1.0, 1.0)]*18,
                                   options={'maxiter': min(50, final_budget), 'ftol': 1e-14, 'gtol': 1e-12})
                    if np.isfinite(res.fun) and res.fun < self.best_f:
                        self.best_f = res.fun
                        self.best_x = np.concatenate([np.clip(res.x, -1.0, 1.0), cats_lb])
                except: pass

        return self.best_f, self.best_x

import numpy as np
from scipy.optimize import minimize

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)
        self.rng = np.random.default_rng()
